import{_ as t,o as l,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const y=JSON.parse('{"title":"CDS Infernalis (Day 1) -- Simple ceph-mon dm-crypt key management","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- Simple ceph-mon dm-crypt key management","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph","dm","crypt","密钥管理","Lux","监控器"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_Simple_ceph-mon_dm-crypt_key_management.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_Simple_ceph-mon_dm-crypt_key_management.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Infernalis_Day_1_--_Simple_ceph-mon_dm-crypt_key_management.md"};function r(p,e,_,a,o,m){return l(),n("div",null,[...e[0]||(e[0]=[i("<p>会议纪要：</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Milanis, Sam, Simulon, Dr. Bras, Danny</p><p><strong>会议主题</strong>： 讨论Ceph存储系统中OSD的dm-crypt密钥管理方案</p><p><strong>关键细节</strong>：</p><ul><li><strong>当前方案</strong>： 使用theftdisk配置dm-crypt进行加密，密钥存储在etsy和csf keys中，安全级别较低。</li><li><strong>目标</strong>： 设计一个更安全的密钥管理方案，替代etsy keys。</li><li><strong>方案讨论</strong>： <ul><li>使用Lux存储dm-crypt密钥，并存储其他信息如UUID。</li><li>密钥存储方式：监控器、Linux密钥系统、使用UID作为密钥。</li><li>密钥撤销：设计可撤销的密钥，以便在磁盘丢失或损坏时撤销访问权限。</li><li>密钥存储位置：Lux头文件或监控器。</li><li>加密方式：使用AES或其他加密算法。</li><li>CLI会话加密：在CLI与监控器之间启用加密会话。</li></ul></li><li><strong>决定的事项</strong>： <ul><li>初步方案：使用Lux存储密钥，并使用另一个密钥允许获取它。</li><li>后续行动计划： <ul><li>完善Lux头文件的使用，确保其安全性。</li><li>设计可撤销的密钥。</li><li>实现CLI会话加密。</li></ul></li></ul></li><li><strong>其他事项</strong>： <ul><li>讨论Lux与密钥存储方案的结合使用。</li><li>讨论CLI会话加密的重要性。</li><li>讨论磁盘丢失或损坏时的密钥管理方案。</li></ul></li></ul><p><strong>改进后的总结</strong>：</p><p>在本次会议中，团队讨论了Ceph存储系统中OSD的dm-crypt密钥管理方案。当前方案使用theftdisk进行加密，但密钥存储在etsy和csf keys中，安全级别较低。会议目标是为Ceph设计一个更安全的密钥管理方案，以替代etsy keys。讨论了多种方案，包括使用Lux存储密钥、使用监控器或Linux密钥系统存储密钥、使用UID作为密钥等。最终决定使用Lux存储密钥，并使用另一个密钥允许获取它。后续行动计划包括完善Lux头文件的使用、设计可撤销的密钥、实现CLI会话加密等。会议还讨论了Lux与密钥存储方案的结合使用、CLI会话加密的重要性，以及磁盘丢失或损坏时的密钥管理方案。</p>",8)])])}const d=t(s,[["render",r]]);export{y as __pageData,d as default};
